package queuewrites_test

import (
	"testing"

	"github.com/jose-codegourmet/rotra-v2/apps/api/internal/writetest"
)

// Each group replays the cases the TypeScript was captured with (apps/api/testdata/tools/capture-writes-queue.test.mjs, the
// cases generated by gen-writes-queue-cases.py): every answer (status, headers, body) and the rows the steps changed in the
// session, roster, assessment, waitlist, request, saved player, shared entry and notification tables (SnapshotDiff). Go answers
// differently from the Route Handler only where a step says "goExpects" (the deviations log has each).

func TestRosterBatchGolden(t *testing.T) { writetest.Replay(t, "testdata", "roster", build) }

// The single roster operations (add, remove, level, no show, move to waitlist, games, presence, waitlist remove, give slot, fill).
func TestRosterOpsGolden(t *testing.T) { writetest.Replay(t, "testdata", "rosterops", build) }

// Session preparation and the court commands: create, edit, the join switches, start, delete, add, edit and remove a court, open early.
// The TypeScript was captured with TZ=UTC (the servers' zone); the clash texts and the dates of a series are UTC here too.
func TestSessionPrepGolden(t *testing.T) { writetest.Replay(t, "testdata", "prep", build) }

// The club's writes: the invite link, venues, settings and saved players (add, delete, move, club nickname, registration link). A race
// whose winner is not decided is not pinned here.
func TestClubWritesGolden(t *testing.T) { writetest.Replay(t, "testdata", "club", build) }

// Join and match requests: confirm and decline a join request, add and decline a match request, the Auto Queue court fill and the
// drop-out notices (Keep, Remove from roster). The court fill's operation ids are random, so its case files hide them (Case.redact).
func TestRequestsGolden(t *testing.T) { writetest.Replay(t, "testdata", "requests", build) }

// Edit details of a saved player (PATCH /api/club/players/{id}): the name, the email once, the phone when none is on file, and the
// club's own playing style, experience and links of an unclaimed player.
func TestEditDetailsGolden(t *testing.T) { writetest.Replay(t, "testdata", "details", build) }

// The signed-in Player's writes on a public Queue Session, called from the paired Queue origin (the app is player): join, cancel the
// request, I'm here, I'm leaving, I can't make it and the Session invite. The ids a join and a notice make are random, so the case
// file hides them (Case.redact).
func TestPublicSessionWritesGolden(t *testing.T) { writetest.Replay(t, "testdata", "pubjoin", build) }

// Match control and the queue of waiting matches: Put on court, Start, Send back, Move, Swap, Replace player, Substitute, Team wins and
// No result, Invalid, Add match (manual, selection, suggested and reviewed Auto queue drafts), edit, remove and reorder a waiting match, Auto
// queue and Regenerate (the server generates from `n`), and the Auto Queue fill a court command triggers. The ids Auto Queue's fill takes
// from a random operation are hidden by the case files (Case.redact). A write that fails after its changes (a contradicting decision)
// commits the sync conflict row it quarantines the attempt in; the golden rows pin that.
func TestMatchControlGolden(t *testing.T) { writetest.Replay(t, "testdata", "match", build) }

// Session-level commands: Set end time, Extend, Cancel session and Mark session invalid. Session done is TestFinalizeGolden.
func TestSessionFinishGolden(t *testing.T) { writetest.Replay(t, "testdata", "finish", build) }

// The signed-in Player's match request (send, cancel) and Move me to the waitlist on a public session, from the paired Queue origin.
func TestPublicMatchRequestGolden(t *testing.T) { writetest.Replay(t, "testdata", "pubmr", build) }

// Publish results. The result snapshot it reads is written by the finalization drive (TestFinalizeGolden); these cases seed one. The ids a
// first publish makes (the publication, its key, the event) are random and hidden by the case files (Case.redact).
func TestPublishResultsGolden(t *testing.T) { writetest.Replay(t, "testdata", "publish", build) }

// The money: the club's inventory (add, edit, stock step, remove), the payment switches (batch, amount received, Mark all paid) and the cost
// estimate Create session and Edit preparation save beside the session (cases from gen-writes-queue-money-cases.py, captured with TZ=UTC).
// Amounts are integer centavos. A database now() (a column default, the stock step's updated_at) shows as "database now()" in the rows; the
// ids of a shuttle plan line (a version 7 UUID) are pinned by their version. A race whose winner is not decided is in race_money_test.go.
func TestMoneyGolden(t *testing.T) { writetest.Replay(t, "testdata", "money", build) }

// Plays free (D-2026-11-27-01), Record refund (#1014), Reject and Reject and refund of a slot transfer (#1011, #1014), the payment writes on a slot
// with a history (#1013) and Start and Cancel session closing the pending transfers (task 2.12). Cases from gen-writes-queue-transfers-cases.py,
// captured with TZ=UTC.
func TestTransfersGolden(t *testing.T) { writetest.Replay(t, "testdata", "transfers", build) }

// Session done and the projection jobs it drives, POST and GET /api/sessions/{id}/finalization. The stream list, the job list and a few
// arrays the TypeScript reads with no order are compared as sets (the cases name them with "unordered").
func TestFinalizeGolden(t *testing.T) { writetest.Replay(t, "testdata", "finalize", buildWithReads) }

// The club's trusted hosts (GET, POST /api/club/trusted-hosts, DELETE /api/club/trusted-hosts/{clubPlayerId}) and a Queue Session's hosts (GET, POST
// /api/sessions/{id}/hosts, DELETE /api/sessions/{id}/hosts/{clubPlayerId}), D-2026-11-22-01. The two GETs are the signedin package's routes, so the
// group mounts the reads too. The ids a host's registration makes come from a random operation id, and the case files hide them (Case.redact).
func TestHostsGolden(t *testing.T) { writetest.Replay(t, "testdata", "hosts", buildWithReads) }

// The Queue visitor routes: Request to join (POST join-request) and My request (GET my-request), with the receipt in an httpOnly cookie. The
// capture sets the receipt secret to "capture-visitor-receipt-secret"; the Set-Cookie text is the one Next writes. The nosecret file is the same
// routes with the secret unset, which the TypeScript answers with 503 where it needs the receipt.
func TestVisitorGolden(t *testing.T) {
	writetest.Replay(t, "testdata", "visitor", buildVisitor("capture-visitor-receipt-secret"))
}

func TestVisitorWithNoSecretGolden(t *testing.T) {
	writetest.Replay(t, "testdata", "visitor-nosecret", buildVisitor(""))
}

// The Player's sign-out from the Queue session page (POST /api/public-sessions/{slug}/sign-out and its preflight): the origin and content
// type checks, the CORS headers and the answer of the sign-in package's sign-out. The capture has no Supabase, so the Set-Cookie header
// is not compared; TestPlayerSignOutRevokesTheSession pins what the Go sign-out does to the session and the cookies.
func TestPlayerSignOutGolden(t *testing.T) {
	writetest.ReplayFull(t, "testdata", "signout", buildSignOut)
}
